#[derive(Debug)]
struct StripeSubscriptionRequestEndpoint { provider: Rc<dyn StripeSubscriptionProvider> }

#[derive(Debug)]
pub struct StripeSubscriptionEndpoint<P: StripeSubscriptionProvider> { provider: Rc<P>, request_endpoint: StripeSubscriptionRequestEndpoint }
impl<P: StripeSubscriptionProvider> StripeSubscriptionEndpoint<P> {
    pub fn new(provider: P) -> Self {
        let provider = Rc::new(provider);
        let request_provider: Rc<dyn StripeSubscriptionProvider> = provider.clone();
        Self { provider, request_endpoint: StripeSubscriptionRequestEndpoint { provider: request_provider } }
    }
}

impl<P: StripeSubscriptionProvider> NativeRequestEndpoint for StripeSubscriptionEndpoint<P> {
    fn capability_id(&self) -> &'static str { CAPABILITY_ID }
    fn descriptor_version(&self) -> &'static str { DESCRIPTOR_VERSION }
    fn operations(&self) -> &'static [&'static str] { &[
        CREATE_CHECKOUT_SESSION_OPERATION,
        CREATE_PORTAL_SESSION_OPERATION,
        GET_SUBSCRIPTION_OPERATION,
    ] }
    fn typed_endpoint(&self) -> Option<&dyn std::any::Any> { Some(&self.request_endpoint) }
    fn invoke(&self, operation: &str, request: Box<dyn std::any::Any>, context: InvocationContext) -> LocalBoxFuture<'static, Result<Result<Box<dyn std::any::Any>, Box<dyn std::any::Any>>, RuntimeFailure>> {
        match operation {
            CREATE_CHECKOUT_SESSION_OPERATION => {
                let Ok(request) = request.downcast::<CreateCheckoutSessionRequest>() else {
                    return Box::pin(futures::future::ready(Err(RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID })));
                };
                let invocation = Rc::clone(&self.provider).create_checkout_session(context, *request);
                Box::pin(async move {
                    invocation.await.map(|result| {
                        result
                            .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                            .map_err(|error| Box::new(error) as Box<dyn std::any::Any>)
                    })
                })
            },
            CREATE_PORTAL_SESSION_OPERATION => {
                let Ok(request) = request.downcast::<CreatePortalSessionRequest>() else {
                    return Box::pin(futures::future::ready(Err(RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID })));
                };
                let invocation = Rc::clone(&self.provider).create_portal_session(context, *request);
                Box::pin(async move {
                    invocation.await.map(|result| {
                        result
                            .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                            .map_err(|error| Box::new(error) as Box<dyn std::any::Any>)
                    })
                })
            },
            GET_SUBSCRIPTION_OPERATION => {
                let Ok(request) = request.downcast::<GetSubscriptionRequest>() else {
                    return Box::pin(futures::future::ready(Err(RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID })));
                };
                let invocation = Rc::clone(&self.provider).get_subscription(context, *request);
                Box::pin(async move {
                    invocation.await.map(|result| {
                        result
                            .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                            .map_err(|error| Box::new(error) as Box<dyn std::any::Any>)
                    })
                })
            }
            _ => Box::pin(futures::future::ready(Err(RuntimeFailure::UnknownOperation { capability: CAPABILITY_ID, operation: operation.to_owned() }))),
        }
    }
}

